-- League worlds: generated teams and players, chosen on the server.
--
-- Teams and players are generated by @fullcourt/game-engine on the server and
-- written by admin_create_league(), which only the service role can call.
-- Clients can read their own league's world but never write it, so nobody can
-- forge a roster.

-- Leagues created before worlds existed have no teams and can't be played.
-- This only affects pre-launch test data.
delete from public.leagues;

alter table public.leagues
  add column size text not null default 'standard'
    check (size in ('standard', 'compact')),
  add column seed text not null default '',
  add column rng_state bigint[] not null default '{}'
    check (cardinality(rng_state) in (0, 4));

alter table public.leagues alter column seed drop default;

-- Teams ---------------------------------------------------------------------------

create table public.teams (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null references public.leagues (id) on delete cascade,
  abbreviation text not null check (abbreviation ~ '^[A-Z0-9]{3}$'),
  city text not null check (char_length(city) between 1 and 40),
  nickname text not null check (char_length(nickname) between 1 and 40),
  conference text not null check (conference in ('East', 'West')),
  division text not null check (char_length(division) between 1 and 40),
  primary_color text not null check (primary_color ~ '^#[0-9a-f]{6}$'),
  secondary_color text not null check (secondary_color ~ '^#[0-9a-f]{6}$'),
  unique (league_id, abbreviation),
  -- Lets players reference (league_id, team_id) so a player can't sit on
  -- another league's team.
  unique (league_id, id)
);

create index teams_league_idx on public.teams (league_id);

-- Players --------------------------------------------------------------------------

create table public.players (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null references public.leagues (id) on delete cascade,
  team_id uuid,
  first_name text not null check (char_length(first_name) between 1 and 40),
  last_name text not null check (char_length(last_name) between 1 and 40),
  position text not null check (position in ('PG', 'SG', 'SF', 'PF', 'C')),
  age smallint not null check (age between 16 and 50),
  height_inches smallint not null check (height_inches between 60 and 96),
  weight_pounds smallint not null check (weight_pounds between 120 and 400),
  jersey smallint not null check (jersey between 0 and 99),
  overall smallint not null check (overall between 25 and 99),
  potential smallint not null check (potential between 25 and 99),
  inside smallint not null check (inside between 25 and 99),
  mid_range smallint not null check (mid_range between 25 and 99),
  three_point smallint not null check (three_point between 25 and 99),
  free_throw smallint not null check (free_throw between 25 and 99),
  passing smallint not null check (passing between 25 and 99),
  ball_handling smallint not null check (ball_handling between 25 and 99),
  off_rebound smallint not null check (off_rebound between 25 and 99),
  def_rebound smallint not null check (def_rebound between 25 and 99),
  perimeter_d smallint not null check (perimeter_d between 25 and 99),
  interior_d smallint not null check (interior_d between 25 and 99),
  speed smallint not null check (speed between 25 and 99),
  strength smallint not null check (strength between 25 and 99),
  stamina smallint not null check (stamina between 25 and 99),
  foreign key (league_id, team_id)
    references public.teams (league_id, id) on delete set null (team_id)
);

create index players_league_team_idx on public.players (league_id, team_id);

-- The player's own team in a league, chosen with choose_team().
alter table public.leagues
  add column user_team_id uuid,
  add foreign key (id, user_team_id)
    references public.teams (league_id, id) on delete set null (user_team_id);

-- Read access: the league owner only ---------------------------------------------------

alter table public.teams enable row level security;
alter table public.players enable row level security;

grant select on public.teams, public.players to authenticated;

create function app_private.owns_league(target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.leagues
    where id = target and owner_id = (select auth.uid())
  );
$$;

grant usage on schema app_private to authenticated;
grant execute on function app_private.owns_league(uuid) to authenticated;

create policy "teams: league owner can read"
  on public.teams for select
  to authenticated
  using (app_private.owns_league(league_id));

create policy "players: league owner can read"
  on public.players for select
  to authenticated
  using (app_private.owns_league(league_id));

-- Choosing your team -----------------------------------------------------------------

create function public.choose_team(target_league uuid, target_team uuid)
returns public.leagues
language plpgsql
security definer
set search_path = ''
as $$
declare
  league public.leagues;
begin
  select * into league
  from public.leagues
  where id = target_league and owner_id = (select auth.uid())
  for update;

  if not found then
    raise exception 'league_not_found' using errcode = 'P0002';
  end if;
  if league.status <> 'setup' then
    raise exception 'team_already_chosen' using errcode = 'P0001';
  end if;
  if not exists (
    select 1 from public.teams where id = target_team and league_id = target_league
  ) then
    raise exception 'team_not_found' using errcode = 'P0002';
  end if;

  update public.leagues
  set user_team_id = target_team, status = 'active'
  where id = target_league
  returning * into league;

  return league;
end;
$$;

revoke execute on function public.choose_team(uuid, uuid) from public, anon;
grant execute on function public.choose_team(uuid, uuid) to authenticated;

-- Creating a league with its world (server only) ---------------------------------------

-- Clients no longer create leagues directly: every league needs a generated world.
drop function public.create_league(text);

create function public.admin_create_league(
  owner uuid,
  league_name text,
  league_size text,
  league_seed text,
  league_rng_state bigint[],
  world_teams jsonb,
  world_players jsonb
)
returns public.leagues
language plpgsql
security invoker
set search_path = ''
as $$
declare
  created public.leagues;
  expected_teams integer :=
    case league_size when 'standard' then 30 when 'compact' then 12 end;
  team_count integer;
  player_count integer;
begin
  if expected_teams is null then
    raise exception 'invalid_league_size' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('create_league:' || owner::text, 0));

  if (select count(*) from public.leagues where owner_id = owner) >= public.league_limit() then
    raise exception 'league_limit_reached'
      using errcode = 'P0001',
            detail = format('An account can keep up to %s leagues.', public.league_limit());
  end if;

  insert into public.leagues (owner_id, name, size, seed, rng_state)
  values (owner, btrim(league_name), league_size, league_seed, league_rng_state)
  returning * into created;

  insert into public.teams (
    league_id, abbreviation, city, nickname, conference, division,
    primary_color, secondary_color
  )
  select created.id, t.abbreviation, t.city, t.nickname, t.conference,
         t.division, t.primary_color, t.secondary_color
  from jsonb_to_recordset(world_teams) as t(
    abbreviation text, city text, nickname text, conference text,
    division text, primary_color text, secondary_color text
  );
  get diagnostics team_count = row_count;

  insert into public.players (
    league_id, team_id, first_name, last_name, position, age, height_inches,
    weight_pounds, jersey, overall, potential, inside, mid_range, three_point,
    free_throw, passing, ball_handling, off_rebound, def_rebound, perimeter_d,
    interior_d, speed, strength, stamina
  )
  select created.id, team.id, p.first_name, p.last_name, p.position, p.age,
         p.height_inches, p.weight_pounds, p.jersey, p.overall, p.potential,
         p.inside, p.mid_range, p.three_point, p.free_throw, p.passing,
         p.ball_handling, p.off_rebound, p.def_rebound, p.perimeter_d,
         p.interior_d, p.speed, p.strength, p.stamina
  from jsonb_to_recordset(world_players) as p(
    team text, first_name text, last_name text, position text, age smallint,
    height_inches smallint, weight_pounds smallint, jersey smallint,
    overall smallint, potential smallint, inside smallint, mid_range smallint,
    three_point smallint, free_throw smallint, passing smallint,
    ball_handling smallint, off_rebound smallint, def_rebound smallint,
    perimeter_d smallint, interior_d smallint, speed smallint,
    strength smallint, stamina smallint
  )
  join public.teams team
    on team.league_id = created.id and team.abbreviation = p.team;
  get diagnostics player_count = row_count;

  if team_count <> expected_teams or player_count <> team_count * 15
     or player_count <> jsonb_array_length(world_players) then
    raise exception 'invalid_world'
      using errcode = '22023',
            detail = format('Got %s teams and %s players for a %s league.',
                            team_count, player_count, league_size);
  end if;

  return created;
end;
$$;

comment on function public.admin_create_league is
  'Creates a league with its generated world in one transaction. Service role only; enforces the per-account limit.';

revoke execute on function public.admin_create_league(uuid, text, text, text, bigint[], jsonb, jsonb)
  from public, anon, authenticated;
grant execute on function public.admin_create_league(uuid, text, text, text, bigint[], jsonb, jsonb)
  to service_role;
